python3 -c "
import json
with open('/app/resources/treasury_bulletin_1980_05.json', 'r') as f:
    data = json.load(f)

# Find keys containing 'cpi' or 'consumer' (case insensitive)
def search_keys(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'cpi' in k.lower() or 'consumer' in k.lower():
                print(f'Found: {path}.{k}')
                print(f'Value: {v}')
            search_keys(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search_keys(item, f'{path}[{i}]')

search_keys(data)
"

