import json
with open('/app/resources/treasury_bulletin_1980_05.json', 'r') as f:
    data = json.load(f)

# Print some sample data to understand structure
def find_tables(obj, path='', depth=0):
    if depth > 3:
        return
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'table' in k.lower() or 'title' in k.lower():
                print(f'{path}.{k}: {str(v)[:100]}')
            find_tables(v, f'{path}.{k}', depth+1)
    elif isinstance(obj, list) and len(obj) > 0:
        find_tables(obj[0], f'{path}[0]', depth+1)

find_tables(data)
